import{_ as a,o as i,c as o,ae as r}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"Capítulo 2: Marco Teórico y Requisitos del Sistema","description":"","frontmatter":{},"headers":[],"relativePath":"tfm/02_marco_teorico.md","filePath":"tfm/02_marco_teorico.md"}'),s={name:"tfm/02_marco_teorico.md"};function t(n,e,l,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="capitulo-2-marco-teorico-y-requisitos-del-sistema" tabindex="-1">Capítulo 2: Marco Teórico y Requisitos del Sistema <a class="header-anchor" href="#capitulo-2-marco-teorico-y-requisitos-del-sistema" aria-label="Permalink to &quot;Capítulo 2: Marco Teórico y Requisitos del Sistema&quot;">​</a></h1><h2 id="_2-1-estado-del-arte-ia-legal-legaltech" tabindex="-1">2.1. Estado del Arte: IA Legal (LegalTech) <a class="header-anchor" href="#_2-1-estado-del-arte-ia-legal-legaltech" aria-label="Permalink to &quot;2.1. Estado del Arte: IA Legal (LegalTech)&quot;">​</a></h2><p>El uso de PLN (Procesamiento de Lenguaje Natural) en el ámbito legal ha evolucionado desde sistemas basados en reglas (RegEx) a modelos probabilísticos (Transformers).</p><h3 id="_2-1-1-llms-vs-slms" tabindex="-1">2.1.1. LLMs vs SLMs <a class="header-anchor" href="#_2-1-1-llms-vs-slms" aria-label="Permalink to &quot;2.1.1. LLMs vs SLMs&quot;">​</a></h3><ul><li><strong>LLMs (GPT-4)</strong>: Alta capacidad de razonamiento pero coste elevado y privacidad comprometida.</li><li><strong>SLMs (Llama 3)</strong>: Modelos <em>Small Language Models</em> ejecutables en local. Su uso democratiza la IA privada, eliminando la dependencia de nubes extranjeras, factor crítico para la administración pública.</li></ul><h2 id="_2-2-tecnicas-de-recuperacion-de-informacion" tabindex="-1">2.2. Técnicas de Recuperación de Información <a class="header-anchor" href="#_2-2-tecnicas-de-recuperacion-de-informacion" aria-label="Permalink to &quot;2.2. Técnicas de Recuperación de Información&quot;">​</a></h2><h3 id="_2-2-1-rag-retrieval-augmented-generation" tabindex="-1">2.2.1. RAG (Retrieval Augmented Generation) <a class="header-anchor" href="#_2-2-1-rag-retrieval-augmented-generation" aria-label="Permalink to &quot;2.2.1. RAG (Retrieval Augmented Generation)&quot;">​</a></h3><p>Para mitigar las &quot;alucinaciones&quot; de la IA, TenderCheck AI utiliza un enfoque RAG simplificado: se extrae el texto completo del PDF (Contexto), se limpia y se inyecta en el prompt del modelo para obligarle a responder basándose <em>únicamente</em> en esa evidencia.</p><h2 id="_2-3-especificacion-de-requisitos-de-software-srs" tabindex="-1">2.3. Especificación de Requisitos de Software (SRS) <a class="header-anchor" href="#_2-3-especificacion-de-requisitos-de-software-srs" aria-label="Permalink to &quot;2.3. Especificación de Requisitos de Software (SRS)&quot;">​</a></h2><h3 id="_2-3-1-requisitos-funcionales-rf" tabindex="-1">2.3.1. Requisitos Funcionales (RF) <a class="header-anchor" href="#_2-3-1-requisitos-funcionales-rf" aria-label="Permalink to &quot;2.3.1. Requisitos Funcionales (RF)&quot;">​</a></h3><p>El sistema debe cumplir con las siguientes funcionalidades críticas:</p><ul><li><strong>RF-01 Ingesta Documental</strong>: Capacidad para cargar y procesar archivos PDF correspondientes a Pliegos y Ofertas.</li><li><strong>RF-02 Extracción de Texto</strong>: Conversión de contenido PDF a texto plano normalizado.</li><li><strong>RF-03 Identificación de Requisitos</strong>: Uso de IA Local para extraer cláusulas técnicas y administrativas.</li><li><strong>RF-04 Clasificación de Prioridad</strong>: Distinción automática entre requisitos OBLIGATORIOS (Mandatory) y OPCIONALES (Optional/Valued).</li><li><strong>RF-05 Validación de Cumplimiento</strong>: Comparación semántica entre lo exigido en el Pliego y lo ofrecido en la Propuesta.</li><li><strong>RF-06 Panel de Control</strong>: Interfaz gráfica para gestionar licitaciones y visualizar resultados mediante códigos de color (Verde/Rojo/Morado).</li></ul><h3 id="_2-3-2-requisitos-no-funcionales-rnf" tabindex="-1">2.3.2. Requisitos No Funcionales (RNF) <a class="header-anchor" href="#_2-3-2-requisitos-no-funcionales-rnf" aria-label="Permalink to &quot;2.3.2. Requisitos No Funcionales (RNF)&quot;">​</a></h3><ul><li><strong>RNF-01 Privacidad</strong>: Ningún dato debe salir de la infraestructura local del usuario.</li><li><strong>RNF-02 Coste Cero</strong>: El sistema no debe depender de servicios de pago por uso (API Keys).</li><li><strong>RNF-03 Transparencia</strong>: Cada validación debe ir acompañada de la evidencia (cita textual) extraída del documento original.</li><li><strong>RNF-04 Resiliencia</strong>: El sistema debe manejar errores de parseo o caídas del modelo de IA sin bloquearse (Fallbacks).</li></ul><h2 id="_2-4-estandares-y-normativa" tabindex="-1">2.4. Estándares y Normativa <a class="header-anchor" href="#_2-4-estandares-y-normativa" aria-label="Permalink to &quot;2.4. Estándares y Normativa&quot;">​</a></h2><p>El desarrollo se adhiere a los siguientes estándares:</p><ul><li><strong>Calidad de Código</strong>: Clean Architecture y principios SOLID.</li><li><strong>Testing</strong>: Cobertura de código mínima del 80% (Vitest).</li><li><strong>Seguridad</strong>: Validación de tipos en tiempo de ejecución (Zod) y cabeceras de seguridad (Helmet).</li></ul>',17)])])}const p=a(s,[["render",t]]);export{g as __pageData,p as default};
